// frontend/src/components/ConceptBoard.js
import React, { useRef, useState, useEffect } from "react";
import { fetchImages, uploadImage, updateImagePosition, deleteImage, checkServerConnection, updateImageSize } from '../api';

const ConceptBoard = () => {
  const boardRef = useRef(null);
  const fileInputRef = useRef(null);

  const [images, setImages] = useState([]);
  const [draggingId, setDraggingId] = useState(null);
  const [dragOffset, setDragOffset] = useState({ x: 0, y: 0 });
  const [transform, setTransform] = useState({ scale: 1, x: 0, y: 0 });
  const [isPanning, setIsPanning] = useState(false);
  const [panStart, setPanStart] = useState({ x: 0, y: 0 });
  const [hoveredImageId, setHoveredImageId] = useState(null);
  const [resizingId, setResizingId] = useState(null);
  const [resizeStart, setResizeStart] = useState({ x: 0, y: 0, width: 0, height: 0 });

  const [showModal, setShowModal] = useState(false);
  const [pendingImage, setPendingImage] = useState(null);
  const [inputName, setInputName] = useState("");
  const [inputCategory, setInputCategory] = useState("");
  // New state for selecting a lore note to link to
  const [selectedLoreNoteId, setSelectedLoreNoteId] = useState('');
  const [loreNotes, setLoreNotes] = useState([]); // To store LoreNotes from localStorage for linking

  const [isFullscreen, setIsFullscreen] = useState(false);
  const [errorMessage, setErrorMessage] = useState(null);
  const [isLoading, setIsLoading] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [serverOnline, setServerOnline] = useState(false);

  // Synced categories with LoreNotes - this is the key change!
  // These should ideally be fetched from a central source or defined in a shared utility.
  // For now, let's keep them consistent with LoreNotes.js
  const categories = [
    'Characters',
    'World Building', 
    'Music/Audio',
    'Technology',
    'Story/Plot',
    'Antagonists',
    'Environments', // Not in LoreNotes, consider syncing
    'Props',        // Not in LoreNotes, consider syncing
    'Vehicles',     // Not in LoreNotes, consider syncing
    'General'
  ];

  const categoryColors = {
    'Characters': '#EC4899',
    'World Building': '#00dbdd', 
    'Music/Audio': '#4ADE80',
    'Technology': '#f59e0b',
    'Story/Plot': '#8b5cf6',
    'Antagonists': '#FF3D3D',
    'Environments': '#10b981',
    'Props': '#f97316',
    'Vehicles': '#6366f1',
    'General': '#6b7280'
  };

  // Check server connection
  useEffect(() => {
    const checkServer = async () => {
      const isOnline = await checkServerConnection();
      setServerOnline(isOnline);
      if (!isOnline) {
        setErrorMessage("Server is offline. Make sure your backend is running on port 5000");
      }
    };
    
    checkServer();
  }, []);

  // Load images from server AND sync to localStorage for LoreNotes integration
  // Also load LoreNotes from localStorage
  useEffect(() => {
    const loadData = async () => {
      if (!serverOnline) return;
      
      setIsLoading(true);
      try {
        const fetchedImages = await fetchImages();
        if (fetchedImages && Array.isArray(fetchedImages)) {
          // Transform images for the board
          const formattedImages = fetchedImages.map(img => ({
            id: img.id.toString(),
            src: `http://localhost:5000${img.url}`,
            x: img.posX || 100,
            y: img.posY || 100,
            name: img.name || img.originalName || 'Untitled',
            // IMPORTANT: Store loreNoteId if it exists
            loreNoteId: img.loreNoteId ? img.loreNoteId.toString() : null,
            category: img.category || 'General', // This will be overwritten if loreNoteId exists
            width: img.width || 300,
            height: img.height || 150
          }));
          setImages(formattedImages);
          
          // IMPORTANT: Store images in localStorage for LoreNotes integration
          localStorage.setItem('conceptBoard_images', JSON.stringify(formattedImages));
        }

        // Load lore notes from localStorage
        const storedLoreNotes = localStorage.getItem('melodicJustice_loreNotes');
        if (storedLoreNotes) {
          setLoreNotes(JSON.parse(storedLoreNotes));
        }

      } catch (error) {
        console.error('Failed to load data:', error);
        setErrorMessage('Failed to load data. Check if server is running on port 5000.');
      } finally {
        setIsLoading(false);
      }
    };

    loadData();

    // Listen for changes in LoreNotes localStorage as well
    const handleLoreNotesStorageChange = (e) => {
      if (e.key === 'melodicJustice_loreNotes') {
        const storedLoreNotes = localStorage.getItem('melodicJustice_loreNotes');
        if (storedLoreNotes) {
          setLoreNotes(JSON.parse(storedLoreNotes));
        }
      }
    };
    window.addEventListener('storage', handleLoreNotesStorageChange);
    return () => window.removeEventListener('storage', handleLoreNotesStorageChange);

  }, [serverOnline]);

  // Also save to localStorage whenever images change
  useEffect(() => {
    if (images.length > 0) {
      localStorage.setItem('conceptBoard_images', JSON.stringify(images));
    }
  }, [images]);

  // Function to get the effective category of an image
  const getEffectiveImageCategory = (image) => {
    if (image.loreNoteId && loreNotes.length > 0) {
      const linkedNote = loreNotes.find(note => note.id.toString() === image.loreNoteId);
      return linkedNote ? linkedNote.category : image.category;
    }
    return image.category;
  };

  // Handle mouse events for dragging images
  const handleMouseDown = (e, id) => {
    e.stopPropagation();
    const image = images.find((img) => img.id === id);
    setDraggingId(id);
    
    // Calculate the mouse position in board coordinates (accounting for transform)
    const boardRect = boardRef.current.getBoundingClientRect();
    const mouseXInBoard = (e.clientX - boardRect.left - transform.x) / transform.scale;
    const mouseYInBoard = (e.clientY - boardRect.top - transform.y) / transform.scale;
    
    // Store the offset between mouse position (in board coordinates) and image position
    setDragOffset({
      x: mouseXInBoard - image.x,
      y: mouseYInBoard - image.y
    });
  };

  const handleMouseMove = (e) => {
    if (draggingId) {
      // Calculate the new mouse position in board coordinates
      const boardRect = boardRef.current.getBoundingClientRect();
      const mouseXInBoard = (e.clientX - boardRect.left - transform.x) / transform.scale;
      const mouseYInBoard = (e.clientY - boardRect.top - transform.y) / transform.scale;
      
      // Set new position based on mouse position minus the initial offset
      setImages((prev) =>
        prev.map((img) =>
          img.id === draggingId
            ? { 
                ...img, 
                x: mouseXInBoard - dragOffset.x, 
                y: mouseYInBoard - dragOffset.y 
              }
            : img
        )
      );
    } else if (resizingId) {
      // Apply similar transformation for resizing
      const boardRect = boardRef.current.getBoundingClientRect();
      const mouseXInBoard = (e.clientX - boardRect.left - transform.x) / transform.scale;
      const mouseYInBoard = (e.clientY - boardRect.top - transform.y) / transform.scale;
      
      const resizeStartXInBoard = (resizeStart.x - boardRect.left - transform.x) / transform.scale;
      const resizeStartYInBoard = (resizeStart.y - boardRect.top - transform.y) / transform.scale;
      
      const deltaX = mouseXInBoard - resizeStartXInBoard;
      const deltaY = mouseYInBoard - resizeStartYInBoard;
      
      // Rest of resize code using deltaX and deltaY
      setImages((prev) => {
        return prev.map((img) => {
          if (img.id !== resizingId) return img;
          
          let newWidth = resizeStart.width;
          let newHeight = resizeStart.height;
          
          switch (resizeStart.direction) {
            case 'se': // Bottom right corner
              newWidth = Math.max(50, resizeStart.width + deltaX);
              newHeight = Math.max(30, resizeStart.height + deltaY);
              break;
            case 'sw': // Bottom left corner
              newWidth = Math.max(50, resizeStart.width - deltaX);
              newHeight = Math.max(30, resizeStart.height + deltaY);
              return { ...img, x: img.x + deltaX, width: newWidth, height: newHeight };
            case 'ne': // Top right corner
              newWidth = Math.max(50, resizeStart.width + deltaX);
              newHeight = Math.max(30, resizeStart.height - deltaY);
              return { ...img, y: img.y + deltaY, width: newWidth, height: newHeight };
            case 'nw': // Top left corner
              newWidth = Math.max(50, resizeStart.width - deltaX);
              newHeight = Math.max(30, resizeStart.height - deltaY);
              return { ...img, x: img.x + deltaX, y: img.y + deltaY, width: newWidth, height: newHeight };
            default:
              break;
          }
          
          return { ...img, width: newWidth, height: newHeight };
        });
      });
    } else if (isPanning) {
      // No change needed for panning
      setTransform((prev) => ({
        ...prev,
        x: prev.x + (e.clientX - panStart.x),
        y: prev.y + (e.clientY - panStart.y),
      }));
      setPanStart({ x: e.clientX, y: e.clientY });
    }
  };

  const handleMouseUp = async () => {
    if (draggingId && serverOnline) {
      // Update position on the server when dragging ends
      const image = images.find(img => img.id === draggingId);
      if (image) {
        try {
          console.log("Updating position:", image.id, { posX: image.x, posY: image.y });
          await updateImagePosition(image.id, { posX: image.x, posY: image.y });
          console.log("Position updated successfully");
        } catch (error) {
          console.error('Failed to update image position:', error);
          setErrorMessage('Failed to save image position. Server might be offline.');
        }
      }
    }
    
    if (resizingId && serverOnline) {
      // Update size on the server when resizing ends
      const image = images.find(img => img.id === resizingId);
      if (image) {
        try {
          // You'll need to create a new API endpoint for updating size
          await updateImageSize(image.id, { width: image.width, height: image.height });
        } catch (error) {
          console.error('Failed to update image size:', error);
          setErrorMessage('Failed to save image size. Server might be offline.');
        }
      }
    }
    
    setDraggingId(null);
    setResizingId(null);
    setIsPanning(false);
  };

  const handleResizeMouseDown = (e, id, direction) => {
    e.stopPropagation();
    const image = images.find(img => img.id === id);
    setResizingId(id);
    
    // Store absolute client coordinates for consistent calculations
    setResizeStart({
      x: e.clientX, // Store raw screen coordinates
      y: e.clientY,
      width: image.width,
      height: image.height,
      direction: direction
    });
  };

  // Handle wheel events for zooming
  const handleWheel = (e) => {
    e.preventDefault();
    const delta = e.deltaY * -0.001;
    const rect = boardRef.current.getBoundingClientRect();
    
    // Get mouse position relative to the board
    const mouseX = e.clientX - rect.left;
    const mouseY = e.clientY - rect.top;
    
    setTransform((prev) => {
      const newScale = Math.min(3, Math.max(0.2, prev.scale + delta));
      const scaleDelta = newScale / prev.scale;
      
      // Calculate new position to keep zoom centered on mouse
      const newX = prev.x - (mouseX - prev.x) * (scaleDelta - 1);
      const newY = prev.y - (mouseY - prev.y) * (scaleDelta - 1);
      
      return {
        scale: newScale,
        x: newX,
        y: newY,
      };
    });
  };

  const handleBackgroundMouseDown = (e) => {
    if (e.button === 0) {
      setIsPanning(true);
      setPanStart({ x: e.clientX, y: e.clientY });
    }
  };

  // Handle image upload - now with server integration
  const handleAddImageClick = () => {
    if (!serverOnline) {
      setErrorMessage("Server is offline. Connect to server to upload images.");
      return;
    }
    fileInputRef.current.click();
  };

  const handleImageUpload = (e) => {
    const file = e.target.files[0];
    if (!file) return;
    
    if (!serverOnline) {
      setErrorMessage("Server is offline. Cannot upload image.");
      return;
    }
    
    // Check file size - now we can handle files larger than 1MB!
    if (file.size > 10 * 1024 * 1024) { // 10MB limit (set in server)
      setErrorMessage("Image too large. Please select an image smaller than 10MB.");
      return;
    }

    const reader = new FileReader();
    reader.onload = () => {
      // Create an image element to get the natural dimensions
      const img = new Image();
      img.onload = () => {
        // Calculate dimensions to maintain aspect ratio
        const maxWidth = 300; // Increased from 250px
        const aspectRatio = img.naturalWidth / img.naturalHeight;
        const width = maxWidth;
        const height = width / aspectRatio;

        setPendingImage({
          file: file, // Store the actual file for upload
          src: reader.result,
          width: width,
          height: height,
          aspectRatio: aspectRatio,
          originalWidth: img.naturalWidth,
          originalHeight: img.naturalHeight
        });
        setInputName(file.name.split('.')[0] || "Untitled");
        setInputCategory("General"); // Default to General now, can be changed in modal
        setSelectedLoreNoteId(''); // Reset selected lore note
        setShowModal(true);
      };
      img.src = reader.result;
    };
    reader.readAsDataURL(file);
    e.target.value = null; // Reset input so same file can be selected again
  };

  const handleAddImageFromModal = async () => {
    if (!pendingImage || !serverOnline) return;
    
    setIsUploading(true);
    setErrorMessage(null);
    
    try {
      // Determine the category to send to the server
      let finalCategory = inputCategory;
      let linkedLoreNoteId = null;

      if (selectedLoreNoteId) {
        const linkedNote = loreNotes.find(note => note.id.toString() === selectedLoreNoteId);
        if (linkedNote) {
          finalCategory = linkedNote.category; // Set image category to linked note's category
          linkedLoreNoteId = selectedLoreNoteId;
        }
      }

      // Create FormData for file upload
      const formData = new FormData();
      formData.append('file', pendingImage.file);
      formData.append('name', inputName || 'Untitled');
      formData.append('category', finalCategory); // Use finalCategory
      formData.append('posX', '100');
      formData.append('posY', '100');
      formData.append('width', '300');
      formData.append('height', pendingImage.height.toString());
      if (linkedLoreNoteId) {
        formData.append('loreNoteId', linkedLoreNoteId); // Add loreNoteId if linked
      }
      
      // Upload to server
      const uploadResult = await uploadImage(formData);
      
      if (uploadResult) {
        // Add the new image to the board
        const newImage = {
          id: uploadResult.id.toString(),
          src: `http://localhost:5000/uploads/${uploadResult.filename}`,
          x: uploadResult.posX || 100,
          y: uploadResult.posY || 100,
          name: uploadResult.name,
          category: uploadResult.category, // This should now be the derived category
          loreNoteId: uploadResult.loreNoteId ? uploadResult.loreNoteId.toString() : null, // Store it
          width: uploadResult.width || 300,
          height: uploadResult.height || 200
        };
        
        setImages(prevImages => [...prevImages, newImage]);
        
        // Close the modal and reset form
        setShowModal(false);
        setInputName("");
        setInputCategory("General");
        setSelectedLoreNoteId("");
        setPendingImage(null);
      }
    } catch (error) {
      console.error('Failed to upload image:', error);
      setErrorMessage(`Failed to upload image: ${error.message}`);
    } finally {
      setIsUploading(false);
    }
  };

  // Function to handle updating an image's category (and potentially loreNoteId)
  const handleUpdateImageCategory = async (imageId, newCategory, newLoreNoteId = null) => {
    if (!serverOnline) {
      setErrorMessage("Server is offline. Cannot update image category.");
      return;
    }

    // Find the current image
    const currentImage = images.find(img => img.id === imageId);
    if (!currentImage) return;

    // Determine the category to send (either newCategory or derived from newLoreNoteId)
    let categoryToSend = newCategory;
    let loreNoteIdToSend = newLoreNoteId;

    if (newLoreNoteId) {
      const linkedNote = loreNotes.find(note => note.id.toString() === newLoreNoteId);
      if (linkedNote) {
        categoryToSend = linkedNote.category; // Override category if linking to a note
      }
    } else {
        // If unlinking, ensure category is set to what was manually selected
        // Or set to 'General' if no manual category was previously set.
        // For simplicity, we'll just use the newCategory passed.
    }


    try {
      // Assuming you have an API endpoint to update image details (like category and loreNoteId)
      // This will need to be added to your `api.js` and backend.
      // Example: updateImageDetails(imageId, { category: categoryToSend, loreNoteId: loreNoteIdToSend })
      
      // For now, let's simulate the API call and update local state
      // You'll need to implement the actual API call
      console.log(`Simulating API call: updateImageDetails(${imageId}, { category: ${categoryToSend}, loreNoteId: ${loreNoteIdToSend} })`);
      // Replace with actual API call:
      // await updateImageDetails(imageId, { category: categoryToSend, loreNoteId: loreNoteIdToSend }); 

      setImages(prevImages => prevImages.map(img => 
        img.id === imageId 
          ? { 
              ...img, 
              category: categoryToSend, 
              loreNoteId: loreNoteIdToSend 
            } 
          : img
      ));
      setErrorMessage(null); // Clear any previous error
    } catch (error) {
      console.error('Failed to update image category/link:', error);
      setErrorMessage('Failed to update image category/link. Server might be offline or API endpoint missing.');
    }
  };

  // Handle fullscreen toggle
  const toggleFullscreen = () => {
    if (!document.fullscreenElement) {
      boardRef.current.requestFullscreen().catch(err => {
        console.error(`Error attempting to enable fullscreen: ${err.message}`);
      });
      setIsFullscreen(true);
    } else {
      document.exitFullscreen();
      setIsFullscreen(false);
    }
  };

  // Delete an image
  const handleDeleteImage = async (id) => {
    if (!serverOnline) {
      setErrorMessage("Server is offline. Cannot delete image.");
      return;
    }
    
    try {
      await deleteImage(id);
      const updatedImages = images.filter(img => img.id !== id);
      setImages(updatedImages);
    } catch (error) {
      console.error('Failed to delete image:', error);
      setErrorMessage('Failed to delete image. Server might be offline.');
    }
  };

  // Set up event listeners
  useEffect(() => {
    const board = boardRef.current;
    if (board) {
      board.addEventListener("wheel", handleWheel, { passive: false });
      return () => board.removeEventListener("wheel", handleWheel);
    }
  }, []);

  // Handle fullscreen change event
  useEffect(() => {
    const handleFullscreenChange = () => {
      setIsFullscreen(!!document.fullscreenElement);
    };
    document.addEventListener('fullscreenchange', handleFullscreenChange);
    return () => document.removeEventListener('fullscreenchange', handleFullscreenChange);
  }, []);

  // Close error message after timeout
  useEffect(() => {
    if (errorMessage) {
      const timer = setTimeout(() => {
        setErrorMessage(null);
      }, 5000);
      return () => clearTimeout(timer);
    }
  }, [errorMessage]);


  return (
    <div className="rounded-lg p-4 w-full max-w-full" style={{ backgroundColor: '#1a1a1a' }}>
      <div className="flex justify-between items-center mb-6">
        <div>
          <h2 className="text-2xl font-bold text-white mb-2">Concept Board</h2>
          <p className="text-gray-400">Organize and manage concept art and reference images</p>
          {!serverOnline && (
            <p className="text-red-400 text-sm mt-1">⚠️ Server offline - Images stored locally only</p>
          )}
        </div>
        
        <div className="flex gap-2">
          <button
            onClick={handleAddImageClick}
            className={`px-4 py-2 rounded-lg flex items-center gap-2 ${
              serverOnline 
                ? 'bg-teal-500 text-white hover:bg-teal-600' 
                : 'bg-gray-600 text-gray-300 cursor-not-allowed'
            } transition-all`}
            disabled={!serverOnline}
          >
            <span>+ Add Image</span>
          </button>
          
          <button
            onClick={toggleFullscreen}
            className="p-2 rounded-lg bg-gray-700 text-white hover:bg-gray-600 transition-all"
          >
            {isFullscreen ? "Exit Fullscreen" : "Fullscreen"}
          </button>
        </div>
      </div>
      
      {/* Connection status indicator */}
      <div className="mb-4 flex items-center gap-2">
        <div 
          className={`w-3 h-3 rounded-full ${serverOnline ? 'bg-green-500' : 'bg-red-500'}`}
        />
        <span className="text-white text-sm">
          Server {serverOnline ? 'Connected' : 'Disconnected'}
        </span>
      </div>
      
      {/* Error message */}
      {errorMessage && (
        <div 
          style={{ 
            backgroundColor: '#f44336', 
            color: 'white', 
            padding: '10px', 
            borderRadius: '4px',
            marginBottom: '10px'
          }}
        >
          {errorMessage}
          <button 
            onClick={() => setErrorMessage(null)} 
            style={{ 
              marginLeft: '10px', 
              background: 'rgba(255,255,255,0.2)', 
              border: 'none', 
              borderRadius: '50%', 
              width: '20px', 
              height: '20px',
              cursor: 'pointer',
              display: 'inline-flex',
              alignItems: 'center',
              justifyContent: 'center',
              lineHeight: 1
            }}
          >×</button>
        </div>
      )}
      
      {/* Loading indicator */}
      {isLoading && (
        <div style={{ textAlign: 'center', color: '#fff', padding: '20px' }}>
          Loading images from server...
        </div>
      )}
      
      <div
        ref={boardRef}
        onMouseDown={handleBackgroundMouseDown}
        onMouseMove={handleMouseMove}
        onMouseUp={handleMouseUp}
        onMouseLeave={handleMouseUp}
        style={{
          position: "relative",
          width: "100%",
          maxWidth: "100vw",
          height: "calc(80vh - 180px)",
          backgroundColor: "#1a1a1a",
          overflow: "hidden",
          cursor: isPanning ? "grabbing" : "grab",
        }}
      >
        {/* Concept Images */}
        <div
          style={{
            transform: `translate(${transform.x}px, ${transform.y}px) scale(${transform.scale})`,
            transformOrigin: "0 0",
            position: "absolute",
            top: 0,
            left: 0,
          }}
        >
          {images.map((img) => {
            const effectiveCategory = getEffectiveImageCategory(img);
            return (
            <div
              key={img.id}
              style={{
                position: "absolute",
                left: img.x,
                top: img.y,
                width: img.width,
                cursor: draggingId === img.id ? "grabbing" : "move",
                userSelect: "none",
                borderRadius: "8px",
                padding: "0px",
                transition: "box-shadow 0.2s ease-in-out",
                boxShadow: hoveredImageId === img.id 
                  ? "0 8px 32px rgba(0,0,0,0.4)" 
                  : "0 4px 16px rgba(0,0,0,0.3)",
              }}
              onMouseDown={(e) => handleMouseDown(e, img.id)}
              onMouseEnter={() => setHoveredImageId(img.id)}
              onMouseLeave={() => setHoveredImageId(null)}
            >
              {/* Delete button - only visible on hover */}
              {hoveredImageId === img.id && (
                <div className="absolute -top-2 -right-2 z-10">
                  <button 
                    onClick={(e) => {
                      e.stopPropagation();
                      handleDeleteImage(img.id);
                    }}
                    className="w-8 h-8 bg-red-500 text-white rounded-full flex items-center justify-center 
                               shadow-lg hover:bg-red-600 transition-colors"
                  >
                    <span className="text-lg leading-none">×</span>
                  </button>
                </div>
              )}
              
              <img
                src={img.src}
                alt={img.name}
                style={{
                  width: "100%",
                  height: "100%",
                  borderRadius: "8px",
                  pointerEvents: "none",
                  objectFit: "cover",
                  display: "block",
                }}
                draggable={false}
              />
              
              {/* Resize handles - only visible on hover */}
              {hoveredImageId === img.id && (
                <>
                  {/* Corner resize handles */}
                  <div
                    className="absolute bottom-0 right-0 w-4 h-4 bg-white border border-gray-400 cursor-se-resize"
                    onMouseDown={(e) => handleResizeMouseDown(e, img.id, 'se')}
                    style={{ transform: 'translate(50%, 50%)' }}
                  />
                  <div
                    className="absolute bottom-0 left-0 w-4 h-4 bg-white border border-gray-400 cursor-sw-resize"
                    onMouseDown={(e) => handleResizeMouseDown(e, img.id, 'sw')}
                    style={{ transform: 'translate(-50%, 50%)' }}
                  />
                  <div
                    className="absolute top-0 right-0 w-4 h-4 bg-white border border-gray-400 cursor-ne-resize"
                    onMouseDown={(e) => handleResizeMouseDown(e, img.id, 'ne')}
                    style={{ transform: 'translate(50%, -50%)' }}
                  />
                  <div
                    className="absolute top-0 left-0 w-4 h-4 bg-white border border-gray-400 cursor-nw-resize"
                    onMouseDown={(e) => handleResizeMouseDown(e, img.id, 'nw')}
                    style={{ transform: 'translate(-50%, -50%)' }}
                  />
                </>
              )}
              
              {/* Caption and Category Selector - only visible on hover */}
              {hoveredImageId === img.id && (
                <div className="absolute bottom-0 left-0 right-0 bg-black bg-opacity-80 p-3 rounded-b-lg">
                  <div className="text-white text-center">
                    <div className="font-semibold text-sm mb-1">{img.name}</div>
                    <select
                      value={img.loreNoteId || effectiveCategory} // Use loreNoteId if linked, else current category
                      onChange={(e) => {
                        const value = e.target.value;
                        if (value.startsWith('loreNote-')) {
                          const noteId = value.substring('loreNote-'.length);
                          handleUpdateImageCategory(img.id, null, noteId); // Link to lore note
                        } else if (value === 'unlink') {
                          handleUpdateImageCategory(img.id, 'General', null); // Unlink, set to General
                        } else {
                          handleUpdateImageCategory(img.id, value, null); // Set direct category
                        }
                      }}
                      onClick={(e) => e.stopPropagation()} // Prevent dragging when clicking select
                      className="text-xs mt-1 px-2 py-1 rounded-full inline-block bg-gray-700 text-white border border-gray-600 cursor-pointer"
                      style={{ 
                        backgroundColor: `${categoryColors[effectiveCategory] || '#6b7280'}40`,
                        color: categoryColors[effectiveCategory] || '#9ca3af'
                      }}
                    >
                      <option value="unlink" disabled={!img.loreNoteId} style={{ backgroundColor: '#333' }}>
                        {img.loreNoteId ? 'Unlink from LoreNote' : 'Select Category'}
                      </option>
                      <optgroup label="LoreNote Categories">
                        {loreNotes.map(note => (
                          <option key={`loreNote-${note.id}`} value={`loreNote-${note.id}`}
                                  style={{ backgroundColor: '#333', color: note.color }}>
                            🔗 {note.title} ({note.category})
                          </option>
                        ))}
                      </optgroup>
                      <optgroup label="General Categories">
                        {categories.filter(cat => cat !== 'All').map(cat => ( // Filter 'All' category
                          <option key={cat} value={cat} style={{ backgroundColor: '#333', color: categoryColors[cat] || '#9ca3af' }}>
                            {cat}
                          </option>
                        ))}
                      </optgroup>
                    </select>
                  </div>
                </div>
              )}
            </div>
           ); // Closes the return statement for the map callback
         })} // Closes the map function call
       </div>

        {/* Empty state */}
        {images.length === 0 && !isLoading && (
          <div style={{
            position: 'absolute',
            top: '50%',
            left: '50%',
            transform: 'translate(-50%, -50%)',
            textAlign: 'center',
            color: '#777'
          }}>
            <p style={{ marginBottom: '10px' }}>No concept images added yet</p>
            {serverOnline ? (
              <button 
                onClick={handleAddImageClick}
                style={{
                  padding: '8px 16px',
                  backgroundColor: '#00d1b2',
                  color: 'white',
                  border: 'none',
                  borderRadius: '4px',
                  cursor: 'pointer'
                }}
              >
                Add Your First Image
              </button>
            ) : (
              <p style={{ color: '#f44336' }}>Server offline - Start your backend server first</p>
            )}
          </div>
        )}

        <input
          ref={fileInputRef}
          type="file"
          accept="image/*"
          onChange={handleImageUpload}
          style={{ display: "none" }}
        />
      </div>

      {/* Upload Modal with synced categories */}
       {showModal && (
        <div style={{
          position: "fixed",
          top: 0,
          left: 0,
          right: 0,
          bottom: 0,
          background: "rgba(0, 0, 0, 0.7)",
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          zIndex: 1000
        }}>
          <div style={{
            background: "#2a2a2a",
            padding: "20px",
            borderRadius: "8px",
            boxShadow: "0 4px 8px rgba(0, 0, 0, 0.2)",
            maxWidth: "400px",
            width: "90%",
            color: "#eee",
            textAlign: "center"
          }}>
            <h3 style={{ marginBottom: "20px", color: "#00d1b2" }}>Image Details</h3>
            {pendingImage && (
              <img
                src={pendingImage.preview}
                alt="Preview"
                style={{
                  maxWidth: "100%",
                  maxHeight: "200px",
                  objectFit: "contain",
                  marginBottom: "15px",
                  borderRadius: "4px"
                }}
              />
            )}
            <div style={{ marginBottom: "15px", textAlign: "left" }}>
              <label htmlFor="imageName" style={{ display: "block", marginBottom: "5px" }}>Image Name:</label>
              <input
                type="text"
                id="imageName"
                value={inputName}
                onChange={(e) => setInputName(e.target.value)}
                style={{
                  width: "100%",
                  padding: "8px",
                  background: "#333",
                  border: "1px solid #555",
                  borderRadius: "4px",
                  color: "#eee"
                }}
                placeholder="Enter image name"
              />
            </div>
            <div style={{ marginBottom: "20px", textAlign: "left" }}>
              <label htmlFor="imageCategory" style={{ display: "block", marginBottom: "5px" }}>Category:</label>
              <select
                id="imageCategory"
                value={inputCategory}
                onChange={(e) => setInputCategory(e.target.value)}
                style={{
                  width: "100%",
                  padding: "8px",
                  background: "#333",
                  border: "1px solid #555",
                  borderRadius: "4px",
                  color: "#eee"
                }}
              >
                <option value="Characters">Characters</option>
                <option value="Environments">Environments</option>
                <option value="Props">Props</option>
                <option value="UI">UI</option>
                <option value="VFX">VFX</option>
                <option value="Concepts">Concepts</option>
                <option value="Storyboards">Storyboards</option>
                <option value="Other">Other</option>
              </select>
            </div>
            
            <div style={{ display: "flex", justifyContent: "space-between", marginTop: "10px" }}>
              <button 
                onClick={() => {
                  setShowModal(false);
                  setPendingImage(null);
                  setInputName("");
                  setInputCategory("Characters");
                }} 
                style={{ 
                  padding: "8px 12px", 
                  background: "#444", 
                  color: "#fff", 
                  border: "none", 
                  borderRadius: "4px",
                  cursor: "pointer"
                }}
                disabled={isUploading}
              >
                Cancel
              </button>
              <button 
                onClick={handleAddImageFromModal} 
                style={{ 
                  padding: "8px 16px", 
                  background: isUploading ? "#666" : "#00d1b2", 
                  color: "#fff", 
                  border: "none", 
                  borderRadius: "4px",
                  cursor: isUploading ? "not-allowed" : "pointer",
                  opacity: isUploading ? 0.7 : 1
                }}
                disabled={isUploading}
              >
                {isUploading ? 'Uploading...' : 'Add Image'}
              </button>
            </div>
          </div>
        </div>
      )} {/* This is the corrected closing for the modal */}
    </div>
  );
};

export default ConceptBoard;
